/* Deployment ladder: what every environment runs, in promotion order. The
   verdict, the table and the notes are all `deploy status` output; nothing here
   colours a row by health, because a row that could not be read is not a row
   that is failing. */
.deploy-verdict {
  margin: 0 0 12px;
  font-size: 13.5px;
  line-height: 1.5;
  padding: 9px 12px;
  border: 1px solid var(--border);
  border-left: 3px solid var(--text-muted);
  border-radius: var(--radius);
  background: var(--surface);
}

/* Agreement across every environment is the claim the command exists to make,
   so it is the one state worth marking. Disagreement is left neutral: the
   sentence already says what it is, and an alarm colour would overstate a
   dev/prod skew that is often just work in progress. */
.deploy-verdict.agrees {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}

.deploy-error {
  margin: 0;
  font-size: 13px;
  line-height: 1.55;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface-2);
  color: var(--text-muted);
  white-space: pre-wrap;
}

.deploy-table {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  font-size: 13px;
}

.deploy-table th,
.deploy-table td {
  text-align: left;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.deploy-table thead th {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  background: var(--surface-2);
}

.deploy-table tbody th {
  font-weight: 600;
  background: var(--surface);
  white-space: nowrap;
}

.deploy-table tbody td {
  background: var(--surface);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
}

.deploy-table tr:last-child th,
.deploy-table tr:last-child td {
  border-bottom: none;
}

/* An environment with no readable overlay keeps its row — omitting it would
   hide exactly the thing an operator needs to see — but reads as absent. */
.deploy-table tr.not-onboarded th {
